 * Returns a `dispose()` to close the stream.
 *
 * Mirrors ant Ds7 (4138.js:126-152).
 */
export function daemonSubscribe(
  op: ProtoOp,
  payload: Record<string, unknown>,
  onMessage: (msg: Response) => void,

